#!/usr/bin/env python3
"""Generate drivers/soc/samsung/gs101-sleep-seq.h from Google's GPL vendor
kernel (drivers/soc/google/cal-if/gs101/flexpmu_cal_system_gs101.h)."""
import re, sys
src = open(sys.argv[1]).read()
WANT = ["enter_sleep", "exit_sleep", "earlywkup_sleep", "exit_sicd", "earlywkup_sicd"]
def ev(x):
    return eval(x.strip(), {}) & 0xffffffff
out = ["/* SPDX-License-Identifier: GPL-2.0 */",
       "/*",
       " * gs101 system power mode sequences, generated by tools/gen-sleep-seq.py",
       " * from Google's vendor kernel (cal-if/gs101/flexpmu_cal_system_gs101.h).",
       " */", ""]
for name in WANT:
    m = re.search(r"struct pmucal_seq %s\[\] = \{(.*?)\n\};" % name, src, re.S)
    body = m.group(1)
    out.append("static const struct gs101_seq gs101_%s[] = {" % name)
    for e in re.finditer(r"PMUCAL_SEQ_DESC\((.*?)\)\s*,\s*(?=PMUCAL_SEQ_DESC|$)", body + "\n", re.S):
        a = [x.strip() for x in re.split(r",(?![^()]*\))", e.group(1).replace("\n", " "))]
        typ, nm = a[0].replace("PMUCAL_", "GS101_SEQ_"), a[1]
        pa, off, mask, val, cpa, coff, cmask, cval = [ev(x) for x in a[2:10]]
        out.append("\t{ %s, 0x%08x, 0x%08x, 0x%08x, 0x%08x, 0x%08x, 0x%08x, 0x%08x }, /* %s */"
                   % (typ, pa + off, mask, val, (cpa + coff) if cpa else 0, cmask, cval, 0, nm.strip('" ')))
    out.append("};\n")
open(sys.argv[2], "w").write("\n".join(out))
